/**
 * Records the committed replay fixture, through the production command path.
 *
 *     npx tsx test/record-replay-fixture.ts
 *
 * **Not a test, and no test runs it.** The repository's golden-file rule is that
 * a committed expectation is an explicit, reviewed change and is never
 * regenerated by a test; the same rule applies here, and more sharply, because a
 * recording is *evidence of an execution*. A suite that could re-record its own
 * inputs on the way to green would be a suite that repairs its way past the
 * failure it exists to report.
 *
 * # What it records, and how
 *
 * ```text
 * dispatch(['run', csrd, CSRD-S-001])   the same entry point verify.ts uses
 *   -> readWorld over the real pack and the real corpus, read-only
 *   -> runVerificationPipeline over the synthetic capability
 *   -> capabilities.record(transcript)  <- the recording, as orchestration built it
 *   -> writeVerificationResult          <- into a temporary directory, discarded
 * ```
 *
 * The recording is therefore the one orchestration assembles on a real run, with
 * the real prompt files, the real closure and the real derived `runId`. Nothing
 * here hand-builds a transcript, and nothing here computes a run identity: a
 * recorder that derived its own `runId` would file recordings under a question
 * only it could ask.
 *
 * # It writes exactly one file, and never into the repository's records
 *
 * `verificationDir` is a temporary directory, so the `verification-result.json`
 * this run produces is written there and deleted. The real
 * `verification/` tree is untouched: no result, no signature, no promotion.
 * The only thing that lands in the checkout is the transcript, under
 * `test/verification-transcripts/`, which the artifact-hygiene guard already
 * forbids from shipping.
 *
 * # When to re-record
 *
 * A recording is bound to the run it answers, so it stops binding when the
 * question moves — a prompt file's bytes, a model id, the role configuration,
 * the requirement, or the corpus closure. `pipeline-replay.test.ts` reds with
 * `TranscriptRunMismatchError` naming the field that moved. **Re-recording is
 * the repair for a deliberate change to one of those, and it is a decision, not
 * a fix**: it retires the recorded outputs as evidence, and the new ones are
 * synthetic until a live run replaces them.
 */

import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { cpSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';

import { EXIT_OK } from '../src/cli/exit-codes';
import { dispatch } from '../src/cli/verify';
import type { VerifyPaths } from '../src/cli/sign';
import { writeRunTranscript, type RunTranscript } from '../src/pipeline/transcript';
import {
  engineRoot,
  FIXTURE_TRANSCRIPT_ROOT,
  PACK_ID,
  REQUIREMENT_ID,
  syntheticCapability,
} from './replay-fixtures';

async function main(): Promise<void> {
  const scratch = mkdtempSync(join(tmpdir(), 'record-replay-fixture-'));
  try {
    // The registry the run's declared requirement version is checked against —
    // copied, so the run reads the repository's own register without being able
    // to write to it.
    mkdirSync(join(scratch, 'requirement-versions'), { recursive: true });
    cpSync(
      join(engineRoot, 'verification', 'requirement-versions', `${PACK_ID}.json`),
      join(scratch, 'requirement-versions', `${PACK_ID}.json`),
    );

    const paths: VerifyPaths = {
      packDir: join(engineRoot, 'knowledge', PACK_ID),
      corpusDir: join(engineRoot, 'corpus'),
      verificationDir: scratch,
    };

    let recorded: RunTranscript | null = null;
    const outcome = await dispatch(
      ['run', PACK_ID, REQUIREMENT_ID],
      paths,
      () => true,
      undefined,
      {
        runner: syntheticCapability(),
        record: (transcript) => {
          recorded = transcript;
        },
      },
    );

    if (outcome.exitCode !== EXIT_OK) {
      throw new Error(
        `the recording run did not complete (exit ${outcome.exitCode}):\n${outcome.lines.join('\n')}`,
      );
    }
    if (recorded === null) {
      throw new Error('the run completed but recorded no transcript');
    }

    const path = writeRunTranscript(FIXTURE_TRANSCRIPT_ROOT, recorded);
    const transcript: RunTranscript = recorded;

    // Provenance, beside the file rather than only in this script's header.
    //
    // The recording states `"model": "claude-opus-5"` on every exchange —
    // truthfully, because that is the model id the role configuration ran under
    // and `pipelineVersion` is derived from it, so it cannot be replaced with a
    // sentinel without changing the identity the recording is filed against.
    // Somebody opening the JSON on its own would have only the `SYNTHETIC
    // FIXTURE` markers inside the role outputs to go on, and the coverage cells
    // carry no free text at all. This note is what makes the directory
    // self-describing. `readTranscriptsFor` reads `*.json` only, so it is inert.
    writeFileSync(
      join(dirname(path), 'PROVENANCE.md'),
      [
        '# Synthetic replay fixture — no model produced this',
        '',
        'Recorded by `backend/engine/test/record-replay-fixture.ts` driving',
        '`syntheticCapability` (`test/replay-fixtures.ts`). **No model was contacted and no',
        'credential existed in the process that wrote it.** The role outputs are hand-written',
        'placeholders that say so in their own words; the evidence quotes are real sentences',
        'from the real corpus, because the evidence checker verifies them against the',
        'documents.',
        '',
        '`model` reads `claude-opus-5` on every exchange. That is the model id the run was',
        'configured with and is a `pipelineVersion` input, so it is recorded truthfully rather',
        'than replaced with a sentinel — it does **not** mean a model answered.',
        '',
        'The first genuine provider transcript does not exist yet. It will use this same format',
        'and this same path, and replacing this file is a decision rather than a fix: it retires',
        'the recorded outputs as evidence.',
        '',
        '## Four generations live here',
        '',
        'A recording is bound to a run identity, so it stops binding when the question moves.',
        'When that happens the old recording is **retired, not deleted**: it is evidence of an',
        'execution that happened, and deleting it would erase the only record of what the',
        'pipeline produced under the previous inputs. `readTranscriptsFor` selects by the',
        'identity a recording is filed under, so retired files are inert — no run can bind to',
        'one by accident.',
        '',
        '| Generation | `runId` | Status |',
        '| --- | --- | --- |',
        '| pre-D1(a) | `run-v1-764e571e…` | retired 2026-08-27 |',
        '| provenance-era | `run-v1-e77e9d0d…` | retired 2026-09-05 |',
        '| standing-era | `run-v1-a6743df7…` | retired 2026-09-05 |',
        `| prompt-era | \`${transcript.runId.slice(0, 20)}…\` | current |`,
        '',
        'The D1(a) provenance migration retired the first. It moved `pipelineVersion` — the',
        'reader prompt changed when locators replaced source identities in `ReaderInput` — and',
        '`requirementInputSha256`, whose domain became the authored `provenance` in place of',
        '`provisions` and `sources`; `runId` follows from both. `packId`, `requirementId`,',
        '`renderedConditionSha256` and `corpusClosureSha256` did **not** move.',
        '',
        'B-E2 retired the second, and this retirement — unlike the migration — **did** move',
        '`corpusClosureSha256`: temporal standing, artefact authenticity and the declared',
        'non-operative sections entered the closure\'s canonical line. `pipelineVersion` moved',
        'with it (identity scheme `v3` hashes the closure policy\'s `expansion` rule and',
        '`closureRendererVersion`), and `runId` follows from both. `packId`, `requirementId`,',
        '`requirementInputSha256` and `renderedConditionSha256` did **not** move.',
        '',
        'B-PROMPT retired the third. The three prompt files gained the rule that closure text',
        'and earlier roles\' output are evidence and never instruction, and the closure',
        'renderer\'s grammar moved to `1.1.0`: every document fenced between lines carrying its',
        'id and hash, heading- and fence-shaped document lines indented, authored titles and',
        'version labels collapsed to one line, carried role output escaped as JSON, and every',
        'message composed through one function that refuses a structural line it did not',
        'write. So `pipelineVersion` moved and `runId` with it. `corpusClosureSha256` did',
        '**not** move: the closure hash covers the stored text, not its rendering. All three',
        'partitions are measured in `pipeline-replay.test.ts` between the retired recordings',
        'themselves, not asserted from a plan.',
        '',
        '`SUPERSEDED_RUN_IDS` in `test/replay-fixtures.ts` is the list of retired identities.',
        'Adding a generation means appending to it, never overwriting a file.',
        '',
        'Regenerate with `npx tsx test/record-replay-fixture.ts` from `backend/engine`.',
        '',
      ].join('\n'),
      'utf8',
    );
    process.stdout.write(
      [
        `Recorded ${transcript.roles.length} role exchange(s)`,
        `  runId           ${transcript.runId}`,
        `  pipelineVersion ${transcript.pipelineVersion}`,
        `  wrote           ${path}`,
        '',
      ].join('\n'),
    );
  } finally {
    rmSync(scratch, { recursive: true, force: true });
  }
}

await main();
